SELECT 
FROM t_gray_metric
WHERE gray_rule_id = #{grayRuleId}
  AND is_deleted = 0

      AND stat_date >= #{startDate}


      AND stat_date <= #{endDate}

ORDER BY stat_date ASC

SELECT 0 AS id, #{grayRuleId} AS gray_rule_id, #{groupType} AS group_type, NULL AS stat_date, SUM(member_count) AS member_count, SUM(receive_count) AS receive_count, SUM(redeem_count) AS redeem_count, SUM(redeem_amount) AS redeem_amount, SUM(order_count) AS order_count, SUM(order_amount) AS order_amount, SUM(refund_count) AS refund_count, SUM(refund_amount) AS refund_amount, CASE WHEN SUM(receive_count) > 0 THEN SUM(redeem_count) * 100.0 / SUM(receive_count) ELSE 0 END AS conversion_rate, CASE WHEN SUM(order_count) > 0 THEN SUM(order_amount) / SUM(order_count) ELSE 0 END AS avg_order_amount FROM t_gray_metric WHERE gray_rule_id = #{grayRuleId} AND group_type = #{groupType} AND is_deleted = 0
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
